using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Text.RegularExpressions;
namespace OwnLabView {
// Methods wrap a pinned own VI; connector rules are set and read through NI.
internal static class ClassMethods {
 internal static Dictionary<string,object> D(params object[] a){var d=new Dictionary<string,object>();for(int i=0;i<a.Length;i+=2)d.Add((string)a[i],a[i+1]);return d;}
 static uint[] Ids(object a){return ((IEnumerable)a).Cast<object>().Select(Convert.ToUInt32).ToArray();}
 internal static void Validate(Dictionary<string,object> doc){if(!doc.ContainsKey("methods"))return;var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var methods=Data.Array(doc["methods"]);if(methods.Length>16)throw new ArgumentException("At most16 methods.");foreach(var raw in methods){var m=Data.Map(raw);Data.Keys(m,"name","source_path","dispatch");string name=Data.Text(m,"name");if(!Regex.IsMatch(name,@"\A[A-Za-z][A-Za-z0-9_]{0,39}\z")||!names.Add(name))throw new ArgumentException("Distinct method names required.");Storage.ArtifactFilename(name+".vi",".vi");string dispatch=m.ContainsKey("dispatch")?Data.Text(m,"dispatch"):"dynamic";if(dispatch!="dynamic"&&dispatch!="static")throw new ArgumentException("Method dispatch must be static or dynamic.");GeneratedViDependency.ValidateOne(Data.Text(m,"source_path"));}}
 internal static object[] Create(object app,List<object> refs,string target,Dictionary<string,object> doc,HashSet<string> seen,Dictionary<string,string> hashes){if(!doc.ContainsKey("methods"))return new object[0];return Data.Array(doc["methods"]).Select(Data.Map).Select(m=>{var member=Build(app,refs,target,Data.Text(m,"name")+".vi",Data.Text(m,"source_path"),m.ContainsKey("dispatch")?Data.Text(m,"dispatch"):"dynamic",null,seen,hashes);if(ClassInterfaces.IsInterface(doc)&&Data.Text(member,"dispatch")=="dynamic")ClassInterfaces.DefaultImplementation(app,refs,target,member,seen,hashes);return (object)member;}).ToArray();}
 static object[] Signature(TypeImport.Session n,string path){
  var info=n.Call("Own20261012_GetConnectorInfo",D("target_path",path),"control_ids");var result=new List<object>();var names=new HashSet<string>(StringComparer.Ordinal);
  foreach(uint id in Ids(info["control_ids"]).Where(x=>x!=0)){
   string label=Convert.ToString(n.Call("Native_GetControlLabel",D("control_id",id),"label")["label"]);if(String.IsNullOrWhiteSpace(label)||label=="self in"||label=="self out"||!names.Add(label))throw new ArgumentException("Method body connector requires unique labels, excluding self in/out.");bool indicator=Convert.ToBoolean(n.Call("Own20261012_GetControlIndicator",D("control_id",id),"is_indicator")["is_indicator"]);uint term=Convert.ToUInt32(n.Call("Native_GetControlTerminal",D("control_id",id),"terminal_id")["terminal_id"]);int[] type=((IEnumerable)n.Call("Native_GetTerminalTypeDescriptor",D("terminal_id",term),"type_string")["type_string"]).Cast<object>().Select(Convert.ToInt32).ToArray();result.Add(new{label,is_indicator=indicator,type_descriptor=type});
  }if(result.Count==0)throw new ArgumentException("Method body needs an assigned connector pane.");return result.ToArray();
 }
 static Dictionary<string,uint> Pins(TypeImport.Session n,uint node){var d=new Dictionary<string,uint>(StringComparer.Ordinal);foreach(uint t in Ids(n.Call("Native_GetNodeTerminals",D("node_id",node),"terminal_ids")["terminal_ids"])){string name=Convert.ToString(n.Call("Native_GetTerminalName",D("terminal_id",t),"terminal_name")["terminal_name"]);if(!String.IsNullOrWhiteSpace(name)&&!d.ContainsKey(name))d.Add(name,t);}return d;}
 static uint Control(TypeImport.Session n,uint term,string label,bool output){string helper=output?"Own20261012_CreateIndicatorFromTerminal":"Own20261012_CreateControlFromTerminal";uint id=Convert.ToUInt32(n.Call(helper,D("terminal_id",term),"control_id")["control_id"]);n.Call("Native_SetControlLabel",D("control_id",id,"label",label));return id;}
 internal static Dictionary<string,object> Build(object app,List<object> refs,string target,string filename,string sourcePath,string dispatch,Dictionary<string,object> expected,HashSet<string> seen,Dictionary<string,string> hashes){
  var source=GeneratedViDependency.ValidateOne(sourcePath);source.VerifyUnchanged();string path=Path.Combine(Path.GetDirectoryName(target),Storage.ArtifactFilename(filename,".vi"));if(File.Exists(path))throw new IOException("Member filename already exists.");
  using(var n=new TypeImport.Session(app,refs)){
   object original=n.Open(source.Path);if(n.Type(original)!=1||Convert.ToInt32(LabView.Invoke(original,"ExecState",BindingFlags.GetProperty))!=1)throw new ArgumentException("Method body must be an executable normal VI.");string[] deps=TypeImport.Session.Paths(original);object[] closure=n.Audit(deps);
   var closureFiles=closure.Select(row=>Data.Map(Data.Json.DeserializeObject(Data.Json.Serialize(row)))).ToArray();
   object[] signature=Signature(n,source.Path);var rows=signature.Select(x=>Data.Map(Data.Json.DeserializeObject(Data.Json.Serialize(x)))).OrderBy(x=>Data.Text(x,"label"),StringComparer.Ordinal).ToArray();
   if(expected!=null){var wanted=Data.Array(expected["signature"]).Select(Data.Map).OrderBy(x=>Data.Text(x,"label"),StringComparer.Ordinal).ToArray();if(Data.Json.Serialize(rows)!=Data.Json.Serialize(wanted))throw new ArgumentException("Override body connector names, directions or native types differ from parent.");}
   string bodyDir=Path.Combine(Path.GetDirectoryName(target),"bodies");var copiedBody=MethodBody.Copy(app,refs,n,source.Path,bodyDir,closure,seen,hashes);string body=copiedBody.Path;
   n.Call("Native_Create",D("output_path",path));object vi=n.Open(path);uint diagram=Convert.ToUInt32(n.Call("Native_GetRootDiagram",D("target_path",path),"diagram_id")["diagram_id"]);
   var constant=n.Call("Native_AddConstantFromTypedef",D("owner_diagram_id",diagram,"typedef_path",target,"x",(short)30,"y",(short)40),"constant_id","terminal_id");uint selfOut=Control(n,Convert.ToUInt32(constant["terminal_id"]),"self out",true);
   foreach(uint wire in Ids(n.Call("Native_GetDiagramWires",D("diagram_id",diagram),"wire_ids")["wire_ids"]))n.Call("Native_DeleteGObject",D("object_id",wire));n.Call("Native_DeleteGObject",D("object_id",constant["constant_id"]));uint outTerm=Convert.ToUInt32(n.Call("Native_GetControlTerminal",D("control_id",selfOut),"terminal_id")["terminal_id"]);uint selfIn=Control(n,outTerm,"self in",false);
   uint bodyNode=Convert.ToUInt32(n.Call("Native_AddSubVIInDiagram",D("target_path",path,"owner_diagram_id",diagram,"subvi_path",body,"x",(short)260,"y",(short)180),"object_id")["object_id"]);var pins=Pins(n,bodyNode);var controls=new List<object>{D("label","self in","identity","self in","is_indicator",false),D("label","self out","identity","self out","is_indicator",true)};var controlIds=new Dictionary<string,uint>{{"self in",selfIn},{"self out",selfOut}};
   foreach(var row in rows){string label=Data.Text(row,"label");bool output=(bool)row["is_indicator"];uint term;if(!pins.TryGetValue(label,out term))throw new IOException("Native body terminal is absent: "+label);controlIds[label]=Control(n,term,label,output);controls.Add(D("label",label,"identity",label,"is_indicator",output));if(!output){object value=LabView.Invoke(original,"_GetCtrlDefaultValVariant",BindingFlags.InvokeMethod,label);LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,label,value);}}
   LabView.Invoke(vi,"MakeCurValueDefault",BindingFlags.InvokeMethod);
   string geometryPath=Path.Combine(Storage.Root,@"recipes\connector-patterns.json");var manifest=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(Path.Combine(Storage.Root,@"recipes\helper-provenance.json"),Encoding.UTF8)));if(Data.Hash(geometryPath)!=Data.Text(manifest,"connector_patterns_sha256"))throw new IOException("Connector geometry changed.");var layout=Recipe.ChooseConnectorLayout(controls.ToArray(),Data.Array(Data.Map(Data.Json.DeserializeObject(File.ReadAllText(geometryPath,Encoding.UTF8)))["patterns"]));
   n.Call("Own20261012_SetConnectorPattern",D("target_path",path,"pattern",layout["pattern"]));foreach(var row in Data.Array(layout["assignments"]).Select(Data.Map))n.Call("Native_AssignConnectorTerminal",D("target_path",path,"control_id",controlIds[Data.Text(row,"label")],"terminal_index",(short)Convert.ToInt32(row["terminal_index"])));
   object library=LabView.Invoke(app,"OpenLibrary",BindingFlags.InvokeMethod,target);refs.Add(library);object item=LabView.Invoke(library,"AddFile",BindingFlags.InvokeMethod,path);refs.Add(item);
   object setter=ClassArtifacts.OpenAuxiliary(app,refs,"OwnMethod20261013_SetWireRule.vi",seen,hashes),getter=ClassArtifacts.OpenAuxiliary(app,refs,"OwnMethod20261013_GetWiringRule.vi",seen,hashes);
   var rules=new List<object>();foreach(var row in Data.Array(layout["assignments"]).Select(Data.Map)){
    string label=Data.Text(row,"label");uint index=Convert.ToUInt32(row["terminal_index"]);ushort rule=(ushort)(dispatch=="dynamic"&&(label=="self in"||label=="self out")?4:(bool)row["is_indicator"]?2:1);LabView.Invoke(setter,"SetControlValue",BindingFlags.InvokeMethod,"target_path",path);LabView.Invoke(setter,"SetControlValue",BindingFlags.InvokeMethod,"TermIdx",index);LabView.Invoke(setter,"SetControlValue",BindingFlags.InvokeMethod,"Rule",rule);LabView.Invoke(setter,"Run",BindingFlags.InvokeMethod,false);ClassArtifacts.CheckError(setter);
    LabView.Invoke(getter,"SetControlValue",BindingFlags.InvokeMethod,"target_path",path);LabView.Invoke(getter,"SetControlValue",BindingFlags.InvokeMethod,"TermIdx",index);LabView.Invoke(getter,"Run",BindingFlags.InvokeMethod,false);ClassArtifacts.CheckError(getter);int actual=Convert.ToInt32(LabView.Invoke(getter,"GetControlValue",BindingFlags.InvokeMethod,"Get Wire Rule"));if(actual!=rule)throw new IOException("NI connector wiring rule differs for "+label+": requested="+rule+", actual="+actual);rules.Add(new{label,index,rule=actual});
   }
   LabView.Invoke(vi,"SaveInstrument",BindingFlags.InvokeMethod,path,false,false);LabView.Invoke(library,"Save",BindingFlags.InvokeMethod,target);if(Convert.ToInt32(LabView.Invoke(vi,"ExecState",BindingFlags.GetProperty))!=1)throw new IOException("Generated custom member not executable.");source.VerifyUnchanged();
   foreach(var entry in closureFiles)if(Data.Hash(Data.Text(entry,"carrier"))!=Data.Text(entry,"sha256"))throw new IOException("Method body dependency changed: "+entry["carrier"]);
   return D("member_kind","custom","path",path,"sha256",Data.Hash(path),"dispatch",dispatch,"signature",rows,"connector",layout,"native_rules",rules.ToArray(),"source_path",source.Path,"source_sha256",source.Sha256,"body_copy",body,"body_copy_sha256",Data.Hash(body),"source_unchanged",true,"generated_member_executed",false,"body_dependency_closure",closure,"body_dependencies_copied",true,"body_snapshot_files",copiedBody.Files);
  }
 }
}
}
